//package com.company;

import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    public static class Task {
        private static final int MOD = 998244353;

        private int add(int a, int b) {
            int c = a + b;
            if (c >= MOD) return c - MOD;
            if (c < 0) return c + MOD;
            return c;
        }

        private int multiply(int a, int b) {
            return (int) ((long) a * b % MOD);
        }

        private int multiply(int... factors) {
            int result = 1;
            for (int f : factors) {
                result = multiply(result, f);
            }
            return result;
        }

        private int[][] stirlingNumbers;

        private void precompute() {
            stirlingNumbers = new int[5001][5001];
            for (int i = 0; i < stirlingNumbers.length; i++) {
                stirlingNumbers[i][0] = 0;
                stirlingNumbers[0][i] = (i == 1) ? 1 : 0;
            }
            for (int i = 1; i < stirlingNumbers.length; i++) {
                stirlingNumbers[i][i] = 1;
            }
            for (int i = 2; i < stirlingNumbers.length; i++) {
                for (int j = 1; j < i; j++) {
                    stirlingNumbers[i][j] = add(multiply(stirlingNumbers[i - 1][j], i - 1), stirlingNumbers[i - 1][j - 1]);
                }
            }
        }

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            precompute();
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();

            BigInteger bigM = BigInteger.valueOf(m);
            BigInteger bigMod = BigInteger.valueOf(MOD);
            int invM = bigM.modInverse(bigMod).intValue();

            int[] pValues = new int[5001];
            pValues[0] = 1;
            int currentM = n;
            int powerTerm = 1;

            for (int i = 1; i <= k; i++) {
                powerTerm = multiply(powerTerm, currentM, invM);
                currentM = add(currentM, -1);

                int subtraction = powerTerm;
                for (int j = i - 1; j >= 1; j--) {
                    int term = stirlingNumbers[i][j];
                    if ((i - j) % 2 == 1) {
                        subtraction = add(subtraction, multiply(term, pValues[j]));
                    } else {
                        subtraction = add(subtraction, add(0, -multiply(term, pValues[j])));
                    }
                }
                pValues[i] = subtraction;
            }

            pw.println(pValues[k]);
        }
    }

    private static long startTime, endTime;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));

        Runtime runtime = Runtime.getRuntime();
        long usedMemoryBefore = runtime.totalMemory() - runtime.freeMemory();
        startTime = System.currentTimeMillis();

        Task task = new Task();
        task.solve(sc, pw);

        endTime = System.currentTimeMillis();
        long usedMemoryAfter = runtime.totalMemory() - runtime.freeMemory();

        pw.close();
        System.err.println("Memory increased: " + (usedMemoryAfter - usedMemoryBefore) / 1000000);
        System.err.println("Time used: " + (endTime - startTime) + ".");
    }

    static class Scanner {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public Scanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public Scanner(FileReader fileReader) throws FileNotFoundException {
            reader = new BufferedReader(fileReader);
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public boolean ready() throws IOException {
            return reader.ready();
        }
    }
}
